from PIL import Image
import requests
import os
def draw():
    s = '@#S%?*+;:,.'
    try:
        img = Image.open('tj.jpg').convert('L')  # 'L' 表示灰度模式
    except Exception as e:
        print(f"图片打开失败: {e}")
        exit()
    width, height = img.size

    char_image = []
    for y in range(height):
        row = []
        for x in range(width):
            pixel_value = img.getpixel((x, y))
            index = pixel_value // 25
            row.append(s[index])
        char_image.append(''.join(row))

    output_path = 'tj.txt'
    try:
        with open(output_path, 'w', encoding='utf-8') as f:
            f.write('\n'.join(char_image))
        print(f"字符画已成功保存到 {output_path}")
    except Exception as e:
        print(f"文件保存失败: {e}")

if __name__ == '__main__':
    draw()
